import {portalAllows,portalForRole,coordinatorSummary} from './portal.mjs';
import {Workspace,ROLES,canManage,canReport,isoDate,eventHasEnded} from './model.mjs';
import {createAuthClient} from '@neondatabase/auth/next';
const authClient=createAuthClient();
const emptyState=()=>({version:2,users:[],events:[],institutions:[],contacts:[],registrations:[],participation:[],outcomes:[],notifications:[],audit:[],settings:{defaultCapacity:120,defaultMode:'Offline'}});
class ServerWorkspace extends Workspace{
 count(id){return this.data.events.find(e=>e.id===id)?.registrationCount??super.count(id)}
 saveEvent(_actor,values,id,submit=false){return rpc('saveEvent',{values,id,submit})}
 transition(_actor,id,action,comments=''){return rpc('transition',{id,action,comments})}
 register(_actor,id){return rpc('register',{id})}
 cancelRegistration(_actor,id){return rpc('cancelRegistration',{id})}
 saveInstitution(_actor,values,id){return rpc('saveInstitution',{values,id})}
 saveContact(_actor,values,id){return rpc('saveContact',{values,id})}
 setPrimaryContact(_actor,institutionId,contactId){return rpc('setPrimaryContact',{institutionId,contactId})}
 recordParticipation(_actor,values){return rpc('recordParticipation',{values})}
 recordOutcome(_actor,values){return rpc('recordOutcome',{values})}
 updateUser(_actor,id,values){return rpc('updateUser',{id,values})}
 updateProfile(_actor,values){return rpc('updateProfile',{values})}
 updateConfiguration(_actor,values){return rpc('updateConfiguration',{values})}
 updatePublishedEvent(_actor,id,values){return rpc('updatePublishedEvent',{id,values})}
 reminders(_actor,id){return rpc('reminders',{id})}
}
let data=emptyState(),store=new ServerWorkspace(data),session=null,page='Overview',selected=null,query='',statusFilter='All statuses',categoryFilter='All categories',menuOpen=false,toastTimer,authMode='login',authIdentity=null,refreshing=false;
let portal=null;try{portal=sessionStorage.getItem('ic-portal');if(!['Student','Coordinator'].includes(portal))portal=null}catch{}
let eventDate='',registrationEvent='All events',registrationStatus='All statuses',institutionType='All types',relationship='All relationships';
function choosePortal(value){portal=value;try{if(value)sessionStorage.setItem('ic-portal',value);else sessionStorage.removeItem('ic-portal')}catch{}}
let theme=(typeof localStorage!=='undefined'&&localStorage.getItem('ic-theme'))||(typeof window!=='undefined'&&window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');
function applyTheme(t){theme=t;if(typeof document!=='undefined'){document.documentElement.setAttribute('data-theme',t);try{localStorage.setItem('ic-theme',t)}catch{}}}
function toggleTheme(){applyTheme(theme==='dark'?'light':'dark')}
applyTheme(theme);
async function readResponse(response){const payload=await response.json();if(!response.ok){const error=new Error(payload.error||'The request could not be completed.');error.code=payload.code;error.status=response.status;throw error}return payload}
function applyState(payload){data=payload.state;store=new ServerWorkspace(data);session=payload.userId}
async function rpc(action,args){const payload=await readResponse(await fetch('/api/workspace',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Institute-Portal':portal||''},body:JSON.stringify({action,args,requestId:crypto.randomUUID()})}));applyState(payload);return payload.result}
async function loadWorkspace(){if(refreshing)return;refreshing=true;try{const response=await fetch('/api/workspace',{credentials:'same-origin',cache:'no-store',headers:{'X-Institute-Portal':portal||''}});const payload=await readResponse(response);applyState(payload);render()}catch(e){if(e.status===401){session=null;authIdentity=null;authMode='login';login()}else if(e.code==='PORTAL_MISMATCH'){session=null;data=emptyState();store=new ServerWorkspace(data);login();const box=document.querySelector('#auth-error');box.textContent=e.message;box.classList.add('visible')}else if(e.code==='EMAIL_VERIFICATION_REQUIRED'){session=null;authMode='verify';login()}else{app.innerHTML=`<div class="empty"><h2>We couldn’t connect to your workspace.</h2><p>${esc(e.message)}</p>${button('Try again','refresh')}${button('Sign out','logout')}</div>`}}finally{refreshing=false}}
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),modalContent=document.querySelector('#modal-content');
const icons={home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z M9 21v-8h6v8',calendar:'M4 5h16v16H4z M7 3v4 M17 3v4 M4 10h16 M8 14h2 M14 14h2 M8 17h2',building:'M4 21V5l8-3 8 3v16 M2 21h20 M8 8h1 M15 8h1 M8 12h1 M15 12h1 M10 21v-5h4v5',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',check:'M5 12l4 4L19 6',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',chart:'M4 3v18h17 M8 17v-5 M13 17V7 M18 17V4',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 5v14 M5 12h14',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',cap:'M2 9l10-5 10 5-10 5z M6 11v7c4 3 8 3 12 0v-7 M22 9v8',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',logout:'M9 21H3V3h6 M10 12h11 M17 8l4 4-4 4',menu:'M3 5h18 M3 12h18 M3 19h18',close:'M5 5l14 14 M19 5L5 19',mail:'M3 5h18v14H3z M3 5l9 8 9-8',activity:'M2 12h5l3-9 4 18 3-9h5',book:'M4 3h7v18H4z M14 3h6v18h-6z',edit:'M15 4l5 5 M3 21l5-1L21 7l-5-5L3 15z',sun:'M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0z',moon:'M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.calendar}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=esc;
const button=(label,action,value='',cls='')=>`<button ${action==='close-modal'?'aria-label="Close dialog"':(action==='nav'&&value==='Notifications')?'aria-label="Notifications"':''} class="${cls}" data-action="${action}" data-value="${attr(value)}">${label}</button>`;
const formatDate=v=>v?new Date(v.slice(0,10)+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'Not set';
const person=id=>data.users.find(u=>u.id===id)?.name||'Unknown user';
const institution=id=>data.institutions.find(u=>u.id===id)?.name||'Independent';
const nowDate=()=>isoDate();
function user(){return data.users.find(u=>u.id===session&&u.status==='Active')}
function persist(){return true}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500)}
async function run(fn,message){try{await fn();render();if(message)toast(message)}catch(e){toast(e.message)}}
function tag(status){const cls=['Published','Confirmed','Active','Present','Approved','Active partner','Registration open'].includes(status)?'green':['Pending','Under Review','In conversation','Opens soon'].includes(status)?'orange':['Cancelled','Rejected','Inactive','Absent','Event cancelled','Full'].includes(status)?'red':['Draft','Completed','Excused','Registration closed','Event ended','Not open'].includes(status)?'gray':'';return `<span class="tag ${cls}">${esc(status==='Pending'?'Submitted':status)}</span>`}
const artwork=()=>`<div class="welcome-art" aria-hidden="true"><div class="orb"></div><div class="art-card"><div class="line"></div><div class="line"></div><div class="line"></div><div class="line"></div></div><div class="art-badge">${icon('cap')}</div></div>`;
function pages(u){const p=['Overview','Events'];if(canManage(u)||u.role==='Institution contact')p.push('Institutions');if(['Approver','Administrator'].includes(u.role))p.push('Approvals');p.push('Registrations');if(canManage(u)||['Student','Institution contact'].includes(u.role))p.push('Participation');if(canManage(u))p.push('Outcomes');if(canReport(u))p.push('Reports');if(u.role==='Administrator')p.push('Users','Audit log');p.push('Notifications','Settings');return p}
const navIcons={'Overview':'home','Events':'calendar','Institutions':'building','Approvals':'shield','Registrations':'people','Participation':'check','Outcomes':'activity','Reports':'chart','Users':'people','Audit log':'book','Notifications':'bell','Settings':'settings'};
function login(){if(!portal){roleSelection();return}const verify=authMode==='verify',signup=authMode==='signup';app.innerHTML=`<div class="login"><section class="login-story"><div class="brand"><span class="brandmark">${icon('cap')}</span>InstituteConnect</div><div><div class="eyebrow">ONE CAMPUS. COUNTLESS CONNECTIONS.</div><h1>Meaningful outreach.<br>Lasting impact.</h1><p>Bring institutions, students, and opportunities together in one secure workspace.</p>${artwork()}</div><div class="small-muted">LNMIIT, Jaipur · Team T005</div></section><section class="login-form"><div style="display:flex;justify-content:flex-end;margin-bottom:12px"><button class="theme-toggle-btn" data-action="toggle-theme" type="button" aria-label="Toggle dark mode" title="${theme==='dark'?'Switch to light mode':'Switch to dark mode'}">${icon(theme==='dark'?'sun':'moon')} &nbsp;<span>${theme==='dark'?'Light mode':'Dark mode'}</span></button></div>${button('← Back to portal selection','portal-back','','subtle')}<div class="eyebrow">${portal==='Coordinator'?'OUTREACH COORDINATOR PORTAL':'PROSPECTIVE STUDENT PORTAL'}</div><h2>${verify?'Verify your email.':signup?'Start your next chapter.':portal==='Coordinator'?'Welcome back, Coordinator.':'Your outreach starts here.'}</h2><p>${verify?'Enter the verification code sent to your email.':'Sign in to discover opportunities and manage institutional outreach.'}</p><form id="auth-form"><div id="auth-error" class="error" role="alert"></div>${signup?'<label>Full name<input name="name" autocomplete="name" required maxlength="150"></label>':''}${verify?`<p class="small-muted">${esc(authIdentity?.email||'Your signed-in email address')}</p><label>Verification code<input name="otp" autocomplete="one-time-code" inputmode="numeric" pattern="[0-9]{6}" required maxlength="6"></label>`:'<label>Email address<input name="email" type="email" autocomplete="username" required maxlength="254"></label><label>Password<input name="password" type="password" autocomplete="'+(signup?'new-password':'current-password')+'" minlength="12" required maxlength="128"></label>'}<button type="submit" class="primary block">${verify?'Verify & open workspace':signup?'Create account':'Sign in'}</button></form>${verify?button('Send verification code','send-code','','block')+button('Sign out','logout','','subtle'):portal==='Coordinator'?'<p class="small-muted">Staff access is assigned by your administrator. Use your verified staff account.</p>':button(signup?'Already registered? Sign in':'New here? Create an account','auth-mode',signup?'login':'signup','subtle')}<p class="demo-note">Your account and records are stored securely in the shared workspace. New accounts start as students; administrators assign staff and institution roles.</p></section></div>`}

function roleSelection(){app.innerHTML=`<div class="login"><section class="login-story"><div class="brand"><span class="brandmark">${icon('cap')}</span>InstituteConnect</div><div><div class="eyebrow">ONE CAMPUS. COUNTLESS CONNECTIONS.</div><h1>Meaningful outreach.<br>Lasting impact.</h1><p>Bring institutions, students, and opportunities together in one secure workspace.</p>${artwork()}</div><div class="small-muted">LNMIIT, Jaipur · Team T005</div></section><section class="login-form portal-choice"><button class="theme-toggle-btn" data-action="toggle-theme" type="button" aria-label="Toggle dark mode">${icon(theme==='dark'?'sun':'moon')} ${theme==='dark'?'Light mode':'Dark mode'}</button><div class="eyebrow">WELCOME TO INSTITUTECONNECT</div><h2>Welcome to InstituteConnect</h2><p>Select how you want to access the portal.</p><div class="portal-options"><article class="portal-card">${icon('cap')}<h3>Prospective Student</h3><p>Discover outreach events and register to participate.</p>${button('Continue as Student','portal-select','Student','primary block')}</article><article class="portal-card">${icon('calendar')}<h3>Outreach Coordinator</h3><p>Organize outreach events, manage institutions, and track participation.</p>${button('Continue as Coordinator','portal-select','Coordinator','primary block')}</article></div><p class="demo-note">Your verified account determines your access. Selecting a portal does not change your assigned role.</p></section></div>`}
function navLabel(u,name){if(!canManage(u))return name;return ({Overview:'Dashboard',Events:'Outreach Events',Institutions:'Institutions & Contacts',Reports:'Outcomes & Reports'})[name]||name}
function coordinatorOverview(u){const summary=coordinatorSummary(data),pending=data.events.filter(e=>['Pending','Under Review'].includes(e.status)),upcoming=data.events.filter(e=>e.status==='Published'&&e.date>=nowDate()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3),recent=[...data.events].sort((a,b)=>(b.updatedAt||b.createdAt||b.history.at(-1)?.date||'').localeCompare(a.updatedAt||a.createdAt||a.history.at(-1)?.date||'')).slice(0,5);return heading('Welcome back, Coordinator',u.role==='Administrator'?'Workspace overview · all outreach events':'Your events, proposals, registrations and outreach impact.',button(icon('plus')+' Create Event','new-event','','primary')+button('Manage Institutions','nav','Institutions'))+stats([['Total outreach events',summary.total,'calendar','In your authorized workspace'],['Draft events',summary.drafts,'edit','Ideas ready to develop'],['Awaiting approval',summary.pending,'shield','Submitted or under review'],['Published / upcoming',summary.upcoming,'clock','Upcoming published events'],['Confirmed registrations',summary.registrations,'people','Across your managed events'],['Participation records',summary.participation,'check','Recorded attendance']])+`<div class="grid-2"><section class="panel"><div class="panel-head"><h2>Recently created or updated</h2></div>${rowsTable(['EVENT','STATUS',''],recent.map(e=>`<tr><td><b>${esc(e.title)}</b><small>${formatDate(e.date)}</small></td><td>${tag(e.status)}</td><td>${button('View event','event',e.id)}</td></tr>`))}</section><section class="panel"><div class="panel-head"><h2>Awaiting approval decisions</h2></div><div class="panel-body">${pending.length?pending.map(e=>`<div class="notice"><b>${esc(e.title)}</b><p>${tag(e.status)} · ${esc(e.history.at(-1)?.comments||'Awaiting an authorized reviewer.')}</p>${button('Track proposal','event',e.id)}</div>`).join(''):empty('No proposals awaiting review.','Save a draft and submit it when ready.')}</div></section></div><div class="section-heading"><h2>Upcoming outreach events</h2>${button('View all events','nav','Events','text-link')}</div><div class="cards">${upcoming.length?upcoming.map(eventCard).join(''):empty('No upcoming events.','Create an event, submit it for review, then publish after approval.')}</div>`}

function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">YOUR OUTREACH WORKSPACE</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`}
function render(){if(!portal){roleSelection();return}const u=user();if(u&&!portalAllows(u.role,portal)){login();return}if(!u){session=null;login();return}const allowed=pages(u);if(!allowed.includes(page))page='Overview';const unread=data.notifications.filter(n=>n.userId===u.id&&!n.read).length;
 app.innerHTML=`<aside class="sidebar ${menuOpen?'open':''}"><div class="brand"><span class="brandmark">${icon('cap')}</span>InstituteConnect</div><div class="workspace-label">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${allowed.filter(p=>!['Settings','Notifications','Audit log'].includes(p)).map(p=>`<button class="${p===page?'active':''}" data-action="nav" data-value="${p}">${icon(navIcons[p])}${navLabel(u,p)}${p==='Approvals'?`<span class="nav-count">${data.events.filter(e=>['Pending','Under Review'].includes(e.status)).length}</span>`:''}</button>`).join('')}${canManage(u)?button(icon('plus')+'Create Event','new-event'):''}</nav><div class="side-bottom"><div class="help-box"><b>Small connections. Big futures.</b><p>Every outreach opens a new door.</p>${button('Workspace guide &nbsp; ↗','guide','','text-link')}</div><nav class="nav">${button(icon('settings')+'Settings','nav','Settings')}${button(icon('logout')+'Sign out','logout')}</nav><div class="team">LNMIIT · Team T005</div></div></aside><div class="mobile-shade" data-action="menu"></div><main class="main"><header class="topbar">${button(icon('menu'),'menu','','menu-toggle')}<div class="breadcrumbs">Workspace &nbsp; / &nbsp; <strong>${esc(page)}</strong></div><div class="top-right"><span class="badge-live">Shared workspace</span>${button(icon(theme==='dark'?'sun':'moon'),'toggle-theme','','theme-toggle-btn')}${button(icon('bell')+(unread?'<span class="dot"></span>':''),'nav','Notifications','bell')}<button class="identity" data-action="profile" type="button" title="View profile info" style="background:transparent;border:0;border-left:1px solid var(--border);border-radius:0;padding:0 0 0 20px;color:inherit;font:inherit;text-align:left;cursor:pointer"><span class="avatar">${esc(u.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><div><b>${esc(u.name)}</b><small>${esc(u.role)}</small></div></button></div></header><div class="content" id="page-content">${content(u)}<footer class="footer"><span>© ${new Date().getFullYear()} InstituteConnect · LNMIIT</span><span>Admissions & outreach, connected.</span></footer></div></main>`;
}
function content(u){if(selected&&page==='Events')return eventDetail(u,store.event(selected));return ({'Overview':overview,'Events':eventsPage,'Institutions':institutionsPage,'Approvals':approvalsPage,'Registrations':registrationsPage,'Participation':participationPage,'Outcomes':outcomesPage,'Reports':reportsPage,'Users':usersPage,'Audit log':auditPage,'Notifications':notificationsPage,'Settings':settingsPage}[page]||overview)(u)}
function stats(items){return `<div class="stats">${items.map(([label,value,ico,sub])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(ico)}</span></div><strong>${value}</strong><small>${sub}</small></div>`).join('')}</div>`}
function summaryStats(u){const student=['Student','Institution contact'].includes(u.role),es=store.visibleEvents(u),rs=data.registrations.filter(r=>(!student||r.userId===u.id)&&r.status==='Confirmed');return stats([[student?'Available events':'Total outreach events',es.length,'calendar',student?'Discover your next opportunity':'Across your outreach lifecycle'],[student?'My registrations':'Confirmed registrations',rs.length,'people',student?'Your confirmed places':'Live registration records'],[student?'My attendance':'Partner institutions',student?data.participation.filter(p=>p.userId===u.id&&p.status==='Present').length:data.institutions.length,'building',student?'Recorded event participation':'Growing our outreach network'],[student?'Upcoming events':'Awaiting approval',es.filter(e=>student?e.status==='Published'&&e.date>=nowDate():['Pending','Under Review'].includes(e.status)).length,'shield',student?'Published & coming up':'Proposals ready for review']])}
function monthlyChart(){const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setMonth(d.getMonth()+i-2,1);return {key:isoDate(d).slice(0,7),label:d.toLocaleDateString('en-IN',{month:'short'})}});const counts=months.map(m=>({events:data.events.filter(e=>e.date?.startsWith(m.key)).length,registrations:data.registrations.filter(r=>r.status==='Confirmed'&&data.events.find(e=>e.id===r.eventId)?.date?.startsWith(m.key)).length}));const max=Math.max(1,...counts.flatMap(c=>[c.events,c.registrations]));return `<div class="panel"><div class="panel-head"><h2>Outreach at a glance</h2><div class="legend"><span>Events</span><span>Registrations</span></div></div><div class="panel-body"><div class="chart" role="img" aria-label="Monthly events and confirmed registrations">${months.map((m,i)=>`<div class="bar-group" title="${m.label}: ${counts[i].events} events, ${counts[i].registrations} registrations"><div class="bar" style="height:${counts[i].events/max*125}px"></div><div class="bar soft" style="height:${counts[i].registrations/max*125}px"></div><span class="bar-label">${m.label}</span></div>`).join('')}</div><p class="small-muted">Based on event dates · current workspace records</p></div></div>`}
function overview(u){if(canManage(u))return coordinatorOverview(u);const upcoming=store.visibleEvents(u).filter(e=>e.status==='Published'&&e.date>=nowDate()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3),isStudent=['Student','Institution contact'].includes(u.role);return heading(`A little outreach. A lot of possibility.`,`Here’s what’s happening across your ${isStudent?'opportunities':'outreach network'} today.`,canManage(u)?button(icon('plus')+' &nbsp; Create event','new-event','','primary'):'')+`<section class="welcome"><div><div class="eyebrow">CONNECT · INSPIRE · GROW</div><h2>Good morning, ${esc(u.name.split(' ')[0])}.<br>Your next connection starts here.</h2><p>${isStudent?'Explore hands-on experiences, meet inspiring people, and take your next step toward a future in engineering.':'From the first school visit to the next generation of engineers, keep every connection moving forward.'}</p></div>${artwork()}</section>`+summaryStats(u)+(canReport(u)?`<div class="grid-2">${monthlyChart()}<div class="panel"><div class="panel-head"><h2>The event pipeline</h2><small>All events</small></div><div class="panel-body pipeline">${['Draft','Pending','Approved','Published','Completed'].map((s,i)=>{const n=data.events.filter(e=>e.status===s).length;return `<div class="pipeline-item"><span class="label">${s==='Pending'?'In review':s}</span><div class="track"><div class="fill" style="width:${100*n/Math.max(1,data.events.length)}%;opacity:${.5+i*.12}"></div></div><b>${n}</b></div>`}).join('')}</div></div></div>`:'')+`<div class="section-heading"><h2>Coming up next</h2>${button('View all events &nbsp; →','nav','Events','text-link')}</div><div class="cards">${upcoming.length?upcoming.map(e=>eventCard(e)).join(''):empty('Your next opportunity is on its way.','Explore all events or create a new event.')}</div>`}
function empty(title,description='Try adjusting your search or filters.'){return `<div class="empty">${icon('calendar')}<h3>${title}</h3><p>${description}</p></div>`}
function eventCard(e){const count=store.count(e.id),date=new Date((e.date||nowDate())+'T12:00:00');return `<article class="event-card"><div class="event-art"><div class="big-icon">${icon(e.category==='Workshop'?'activity':e.category==='Webinar'?'people':'cap')}</div><div class="date-tile">${date.toLocaleDateString('en-IN',{month:'short'}).toUpperCase()}<b>${date.getDate()}</b></div></div><div class="event-body">${tag(e.category)}<h3>${esc(e.title)}</h3><div class="event-meta">${icon('clock')}${esc(e.startTime||'Not set')} – ${esc(e.endTime||'Not set')} IST</div><div class="event-meta">${icon('pin')}${esc(e.venue||'Venue to be confirmed')}</div><div class="event-meta">${icon('people')}${count} / ${e.capacity} registered &nbsp; ${tag(e.status)}</div><div class="event-meta">${tag(store.registrationState(e.id))}</div></div><div class="event-footer"><span>${esc(e.mode)} experience</span>${button('View details &nbsp; ↗','event',e.id)}</div></article>`}
function filters(type){return `<div class="filters"><div class="search">${icon('search')}<input data-filter="search" aria-label="Search ${type}" placeholder="Search ${type}…" value="${attr(query)}"></div>${type==='events'?`<select data-filter="status" aria-label="Filter status">${['All statuses','Draft','Pending','Under Review','Approved','Published','Rejected','Registration closed','Completed','Cancelled'].map(x=>`<option value="${attr(x)}" ${statusFilter===x?'selected':''}>${x==='Pending'?'Submitted':esc(x)}</option>`).join('')}</select><select data-filter="category" aria-label="Filter category">${['All categories','Campus visit','School visit','Workshop','Webinar','Recruitment drive','Other'].map(x=>`<option ${categoryFilter===x?'selected':''}>${x}</option>`).join('')}</select><label class="filter-label">Event date<input type="date" data-filter="event-date" value="${attr(eventDate)}"></label>`:type==='registrations'?`<select data-filter="registration-event" aria-label="Filter registrations by event">${[['All events','All events'],...data.events.map(e=>[e.id,e.title])].map(([id,title])=>`<option value="${attr(id)}" ${registrationEvent===id?'selected':''}>${esc(title)}</option>`).join('')}</select><select data-filter="registration-status" aria-label="Filter registration status">${['All statuses','Confirmed','Cancelled','Event cancelled'].map(x=>`<option ${registrationStatus===x?'selected':''}>${x}</option>`).join('')}</select>`:type==='institutions & contacts'?`<select data-filter="institution-type" aria-label="Filter institution type">${['All types','School','College','Other'].map(x=>`<option ${institutionType===x?'selected':''}>${x}</option>`).join('')}</select><select data-filter="relationship" aria-label="Filter relationship">${['All relationships','New lead','In conversation','Active partner','Inactive'].map(x=>`<option ${relationship===x?'selected':''}>${x}</option>`).join('')}</select>`:''}${button('Clear filters','clear-filters')}</div>`}
function filteredEvents(u){return store.visibleEvents(u).filter(e=>(statusFilter==='All statuses'||(statusFilter==='Registration closed'?store.registrationState(e.id)==='Registration closed':e.status===statusFilter))&&(categoryFilter==='All categories'||e.category===categoryFilter)&&(!eventDate||e.date===eventDate)&&`${e.title} ${e.description} ${e.venue}`.toLowerCase().includes(query.toLowerCase()))}
function eventsPage(u){const es=filteredEvents(u);return heading('Outreach events','A place for every connection, from the first idea to the final impact.',canManage(u)?button(icon('plus')+' Create event','new-event','','primary'):'')+filters('events')+`<div class="list-top">${es.length} ${es.length===1?'event':'events'} in your workspace</div>`+(canManage(u)?rowsTable(['EVENT','SCHEDULE / LOCATION','TARGET INSTITUTIONS','REGISTRATIONS','STATUS',''],es.map(e=>`<tr><td><b>${esc(e.title)}</b><small>${esc(e.category)}</small></td><td>${formatDate(e.date)}<small>${esc(e.startTime)}–${esc(e.endTime)} IST · ${esc(e.mode)}<br>${esc(e.venue)}</small></td><td>${esc(e.institutionIds.map(institution).join(', ')||'All institutions')}</td><td>${store.count(e.id)} / ${e.capacity}</td><td>${tag(e.status)}</td><td>${button('View / manage','event',e.id)}</td></tr>`)):`<div class="cards" id="event-results">${es.length?es.map(eventCard).join(''):empty('No events found')}</div>`)}
function eventDetail(u,e){const rs=data.registrations.filter(r=>r.eventId===e.id&&r.status==='Confirmed'),mine=rs.find(r=>r.userId===u.id),own=canManage(u)&&(u.role==='Administrator'||e.organizerId===u.id);let actions='';if(own){if(['Draft','Rejected'].includes(e.status))actions+=button(icon('edit')+' &nbsp; Edit','edit-event',e.id)+button('Submit for approval','transition',e.id+':submit','primary');if(e.status==='Approved')actions+=button('Publish event','transition',e.id+':publish','primary');if(e.status==='Published'){if(!eventHasEnded(e))actions+=button('Update logistics','update-published',e.id);actions+=button('Send reminders','reminder',e.id);if(eventHasEnded(e))actions+=button('Mark completed','transition',e.id+':complete','primary')}if(!['Completed','Cancelled'].includes(e.status))actions+=button('Cancel event','confirm-cancel',e.id,'danger')}if(['Approver','Administrator'].includes(u.role)&&['Pending','Under Review'].includes(e.status))actions+=button('Review proposal','review',e.id,'primary');
 return button('← All events','back-events','','subtle')+`<div class="page-heading"><div><div class="actions">${tag(e.category)}${tag(e.status)}</div><h1 class="detail-title">${esc(e.title)}</h1><p>Organized by ${esc(person(e.organizerId))}</p></div></div><div class="detail-grid"><div class="panel"><div class="detail-section"><h3>About this experience</h3><p>${esc(e.description||'Add a description before submitting this event.')}</p><div class="actions">${actions}</div></div><div class="detail-section"><h3>What to know</h3><p>${esc(e.instructions||'No additional instructions.')}</p><div class="detail-pair"><span>Eligibility</span><b>${esc(e.eligibility||'All students')}</b></div><div class="detail-pair"><span>Partner institutions</span><b>${esc(e.institutionIds.map(institution).join(', ')||'All institutions')}</b></div></div>${!['Student','Institution contact'].includes(u.role)?`<div class="detail-section"><h3>Associated contacts</h3><p>${esc((e.contactIds||[]).map(id=>data.contacts.find(c=>c.id===id)).filter(Boolean).map(c=>`${c.name} · ${c.email}`).join('\n')||'No specific contacts selected.')}</p><h3>Approval history</h3><div class="timeline">${e.history.length?e.history.map(h=>`<p><b>${esc(h.decision)}</b> · ${esc(person(h.by))}<br>${esc(h.comments)}<br><small>${formatDate(h.date)}</small></p>`).join(''):'<p>No approval decisions yet.</p>'}</div></div>`:''}${canManage(u)?`<div class="detail-section"><h3>Confirmed participants (${rs.length})</h3>${rs.length?rs.map(r=>`<div class="detail-pair"><span>${esc(person(r.userId))}</span><b>${tag(r.status)}</b></div>`).join(''):'<p>No registrations yet.</p>'}</div>`:''}</div><aside><div class="panel"><div class="detail-section"><h3>Event essentials</h3><div class="notice">${esc(store.registrationState(e.id))}</div><div class="detail-pair"><span>Date</span><b>${formatDate(e.date)}</b></div><div class="detail-pair"><span>Time</span><b>${esc(e.startTime)} – ${esc(e.endTime)} IST</b></div><div class="detail-pair"><span>Location</span><b>${esc(e.venue)}</b></div><div class="detail-pair"><span>Mode</span><b>${esc(e.mode)}</b></div><div class="progress"><div style="width:${Math.min(100,store.count(e.id)/e.capacity*100)}%"></div></div><div class="detail-pair"><span>Places filled</span><b>${store.count(e.id)} / ${e.capacity}</b></div><p class="small-muted">Registration: ${formatDate(e.registrationStart)} – ${formatDate(e.registrationEnd)}</p>${['Student','Institution contact'].includes(u.role)?mine?`<div class="notice">You’re on the list. Your place is confirmed.<br>Reference: ${esc(mine.id.slice(0,10))}</div>${e.date>nowDate()?button('Cancel my registration','cancel-registration',mine.id,'block danger'):''}`:(store.registrationState(e.id)==='Registration open'?button('Register for this event','register',e.id,'primary block'):button(store.registrationState(e.id),'register',e.id,'primary block').replace('<button ','<button disabled ')):''}</div></div><div class="notice">${icon('shield')} &nbsp;All events follow an approval process before publication.</div></aside></div>`}
const rowsTable=(headers,rows)=>`<div class="panel table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}">${empty('Nothing here yet.','New records will appear here.')}</td></tr>`}</tbody></table></div>`;
function institutionsPage(u){const own=u.role==='Institution contact';const is=data.institutions.filter(i=>(!own||i.id===u.institutionId)&&(institutionType==='All types'||i.type===institutionType)&&(relationship==='All relationships'||i.status===relationship)&&`${i.name} ${i.region} ${data.contacts.filter(c=>c.institutionId===i.id).map(c=>c.name+' '+c.email+' '+c.phone).join(' ')}`.toLowerCase().includes(query.toLowerCase()));return heading('Our institution network','Keep the people behind every partnership close.',canManage(u)?button(icon('plus')+' &nbsp; Add institution','new-institution','','primary'):'')+filters('institutions & contacts')+rowsTable(['INSTITUTION','REGION','CONTACTS','RELATIONSHIP',''],is.map(i=>`<tr><td><b>${esc(i.name)}</b><small>${esc(i.type)}</small></td><td>${esc(i.region)}</td><td>${esc(data.contacts.find(c=>c.id===i.primaryContactId)?.name||'No primary contact')}<small>${data.contacts.filter(c=>c.institutionId===i.id).length} contacts</small></td><td>${tag(i.status)}</td><td>${button('View institution','institution',i.id)}</td></tr>`))}
function approvalsPage(u){const pending=data.events.filter(e=>['Pending','Under Review'].includes(e.status));return heading('A fresh perspective. A clear decision.','Review outreach proposals and help good ideas move forward.')+stats([['Awaiting review',pending.length,'shield','Proposals requiring a decision'],['Approved decisions',data.events.reduce((n,e)=>n+e.history.filter(h=>h.decision==='Approved').length,0),'check','Across all event histories'],['Rejected decisions',data.events.reduce((n,e)=>n+e.history.filter(h=>h.decision==='Rejected').length,0),'book','With a reason for every decision'],['Published events',data.events.filter(e=>e.status==='Published').length,'calendar','Approved and ready to explore']])+rowsTable(['PROPOSAL','ORGANIZER','DATE','STATUS',''],pending.map(e=>`<tr><td><b>${esc(e.title)}</b><small>${esc(e.category)} · ${e.capacity} places</small></td><td>${esc(person(e.organizerId))}</td><td>${formatDate(e.date)}</td><td>${tag(e.status)}</td><td>${button('Review proposal','review',e.id,'primary')}</td></tr>`))+`<div class="section-heading"><h2>Decision history</h2></div>`+rowsTable(['EVENT','DECISION','REVIEWER','COMMENTS','DATE'],data.events.flatMap(e=>e.history.map(h=>`<tr><td>${esc(e.title)}</td><td>${tag(h.decision)}</td><td>${esc(person(h.by))}</td><td>${esc(h.comments||'—')}</td><td>${formatDate(h.date)}</td></tr>`)))}
function registrationsPage(u){const staff=canManage(u),rs=filteredRegistrations(u);return heading(staff?'Every place. Every participant.':'Your next experiences, all here.',staff?'Registrations for your managed events.':'Keep track of your confirmed places and past experiences.',staff?button(icon('download')+' Export filtered CSV','export-registrations'):'')+filters('registrations')+rowsTable(['EVENT',...(staff?['PARTICIPANT']:[]),'REGISTERED','EVENT DATE','STATUS',''],rs.map(r=>{const e=store.event(r.eventId),participant=data.users.find(x=>x.id===r.userId);return `<tr><td><b>${esc(e.title)}</b><small>Ref. ${esc(r.id.slice(0,10))} · ${store.count(e.id)} / ${e.capacity} places</small></td>${staff?`<td>${esc(person(r.userId))}<small>${esc(participant?.email)}${participant?.phone?'<br>'+esc(participant.phone):''}</small></td>`:''}<td>${formatDate(r.date)}</td><td>${formatDate(e.date)}</td><td>${tag(r.status)}</td><td>${button('View event','event',e.id)} ${!staff&&r.status==='Confirmed'&&e.date>nowDate()?button('Cancel','cancel-registration',r.id,'danger'):''}</td></tr>`}))}
function filteredRegistrations(u){return data.registrations.filter(r=>(canManage(u)||r.userId===u.id)&&(registrationEvent==='All events'||r.eventId===registrationEvent)&&(registrationStatus==='All statuses'||r.status===registrationStatus)&&`${store.event(r.eventId).title} ${person(r.userId)} ${data.users.find(x=>x.id===r.userId)?.email||''} ${r.status}`.toLowerCase().includes(query.toLowerCase()))}
function outcomesPage(u){return heading('Turn experiences into impact.','Capture engagement, feedback, and the next steps that matter.',button(icon('plus')+' &nbsp; Record outcome','new-outcome','','primary'))+`<div class="cards">${data.outcomes.map(o=>`<article class="panel"><div class="detail-section">${tag('Outcome recorded')}<h3 style="margin-top:15px">${esc(store.event(o.eventId).title)}</h3><div class="detail-pair"><span>Institutions engaged</span><b>${o.institutionsEngaged}</b></div><div class="detail-pair"><span>Participants reached</span><b>${o.participantsReached??store.count(o.eventId)}</b></div><div class="detail-pair"><span>Leads generated</span><b>${o.leads}</b></div><p>${esc(o.feedback)}</p><b class="small-muted">FOLLOW-UP</b><p>${esc(o.followUp||'No follow-up required.')}</p><p>${o.followUpRequired?'Follow-up required':''}</p><p>${esc(o.notes||'')}</p><small class="small-muted">${formatDate(o.date)}</small></div></article>`).join('')||empty('Your impact story starts here.','Record an outcome after an outreach event.')}</div>`}
function reportsPage(u){const present=data.participation.filter(p=>p.status==='Present').length;return heading('The bigger picture, made clear.','A live view of outreach, participation, and institutional engagement.',button(icon('download')+' &nbsp; Export event report','export-report')+button('Participation CSV','export-participation')+button('Outcome CSV','export-outcomes')+button('Print report','print'))+stats([['Confirmed registrations',data.registrations.filter(r=>r.status==='Confirmed').length,'people','Excludes cancelled registrations'],['Attendance records',present,'check','Marked present across activities'],['Leads generated',data.outcomes.reduce((n,o)=>n+o.leads,0),'activity','Sum of recorded outcome entries'],['Outcomes recorded',data.outcomes.length,'chart','Event-level impact records']])+`<div class="grid-2">${monthlyChart()}<div class="panel"><div class="panel-head"><h2>Events by category</h2></div><div class="report-bars">${['Workshop','Campus visit','School visit','Webinar','Recruitment drive'].map(c=>{const n=data.events.filter(e=>e.category===c).length;return `<div class="report-row"><span>${c}</span><div class="track"><div class="fill" style="width:${100*n/Math.max(1,data.events.length)}%"></div></div><b>${n}</b></div>`}).join('')}</div></div></div>`+rowsTable(['EVENT','STATUS','REGISTRATIONS','PRESENT RECORDS','LEADS'],data.events.map(e=>`<tr><td><b>${esc(e.title)}</b></td><td>${tag(e.status)}</td><td>${store.count(e.id)} / ${e.capacity}</td><td>${data.participation.filter(p=>p.eventId===e.id&&p.status==='Present').length}</td><td>${data.outcomes.filter(o=>o.eventId===e.id).reduce((n,o)=>n+o.leads,0)}</td></tr>`))}
function usersPage(){return heading('The right people. The right access.','Assign roles, link institution contacts, and manage account access.')+rowsTable(['USER','ROLE','STATUS',''],data.users.map(u=>`<tr><td><b>${esc(u.name)}</b><small>${esc(u.email)}</small></td><td>${esc(u.role)}</td><td>${tag(u.status)}</td><td>${button('Manage account','edit-user',u.id)}</td></tr>`))}
function auditPage(){return heading('A clear record of every step.','Administrative and outreach activity, recorded as it happens.')+rowsTable(['ACTION','BY','DATE'],data.audit.map(a=>`<tr><td>${esc(a.message)}</td><td>${esc(a.by)}</td><td>${esc(new Date(a.date).toLocaleString('en-IN'))}</td></tr>`))}
function notificationsPage(u){const ns=data.notifications.filter(n=>n.userId===u.id);return heading('You’re in the loop.','Registration confirmations, review updates, and event reminders.',button('Mark all read','read-all'))+`<div class="panel">${ns.map(n=>`<div class="notification ${n.read?'':'unread'}"><span class="avatar">${icon('bell')}</span><div>${tag(n.type||'Update')}<p>${esc(n.message)}</p><small>${esc(new Date(n.date).toLocaleString('en-IN'))}</small></div>${!n.read?button('Mark read','read',n.id):''}</div>`).join('')||empty('All caught up.','Your updates will appear here.')}</div><div class="notice">Notifications in this prototype are in-app only. Email and SMS delivery are not configured.</div>`}
function openModal(title,body,submit,submitLabel='Save'){const m=document.querySelector('#modal'),mc=document.querySelector('#modal-content');if(!m||!mc)return;mc.innerHTML=`<div class="modal-head"><h2>${title}</h2>${button(icon('close'),'close-modal','','subtle')}</div><form id="modal-form" class="modal-body"><div class="error" id="form-error" role="alert"></div>${body}${submit?`<div class="modal-footer">${button('Cancel','close-modal')}${submitLabel==='Save as Draft'?'<button type="submit" name="intent" value="submit" class="primary">Submit for Approval</button>':''}<button class="${submitLabel==='Save as Draft'?'':'primary'}" type="submit" name="intent" value="draft">${submitLabel}</button></div>`:''}</form>`;mc.querySelectorAll('button[data-action]').forEach(b=>b.type='button');if(submit)document.querySelector('#modal-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.currentTarget;if(!form.reportValidity())return;const submitButtons=[...form.querySelectorAll('button[type="submit"]')];submitButtons.forEach(b=>b.disabled=true);try{await submit(new FormData(form),ev.submitter?.value||'draft');persist();m.close();render()}catch(e){const er=document.querySelector('#form-error');er.textContent=e.message;er.classList.add('visible')}finally{submitButtons.forEach(b=>b.disabled=false)}};if(!m.open)m.showModal()}
const field=(label,name,value='',type='text',required=false,full=false)=>`<label class="${full?'full':''}">${label}<input ${name==='organizer'?'readonly':''} name="${name}" type="${type}" value="${attr(value)}" ${required?'required':''} ${type==='number'?'min="0" step="1"':''}></label>`;
const area=(label,name,value='',required=false)=>`<label class="full">${label}<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea></label>`;
const select=(label,name,options,value='',full=false)=>`<label class="${full?'full':''}">${label}<select name="${name}">${options.map(o=>{const v=typeof o==='string'?o:o[0],n=typeof o==='string'?o:o[1];return `<option value="${attr(v)}" ${v===value?'selected':''}>${esc(n)}</option>`}).join('')}</select></label>`;
function eventForm(e){const u=user(),v=e||{title:'',description:'',date:'',startTime:'10:00',endTime:'13:00',mode:data.settings.defaultMode,category:'Workshop',capacity:data.settings.defaultCapacity,registrationStart:nowDate(),registrationEnd:'',eligibility:'All students',venue:'',instructions:'',institutionIds:[],contactIds:[]};openModal(e?'Edit event draft':'Create an outreach event',`<p class="small-muted">Save your idea as a draft, then submit it for approval.</p><div class="form-grid">${field('Event title *','title',v.title,'text',true,true)}${area('Description','description',v.description)}${select('Category','category',['Workshop','Campus visit','School visit','Webinar','Recruitment drive','Other'],v.category)}${field('Event date','date',v.date,'date')}${field('Start time (IST)','startTime',v.startTime,'time')}${field('End time (IST)','endTime',v.endTime,'time')}${select('Mode','mode',['Offline','Online','Hybrid'],v.mode)}${field('Capacity *','capacity',v.capacity,'number',true)}${field('Venue / meeting location','venue',v.venue,'text',false,true)}${field('Registration opens','registrationStart',v.registrationStart,'date')}${field('Registration closes','registrationEnd',v.registrationEnd,'date')}${select('Eligibility','eligibility',['All students','Class 10','Class 11','Class 12','Undergraduate'],v.eligibility)}${field('Organizer','organizer',u.name)}<label class="full">Target institutions <small>Hold Ctrl / Cmd to select multiple. Leave empty for all.</small><select name="institutionIds" multiple>${data.institutions.map(i=>`<option value="${attr(i.id)}" ${v.institutionIds.includes(i.id)?'selected':''}>${esc(i.name)}</option>`).join('')}</select></label><label class="full">Associated contacts<select name="contactIds" multiple>${data.contacts.filter(c=>!v.institutionIds.length||v.institutionIds.includes(c.institutionId)).map(c=>`<option value="${attr(c.id)}" ${(v.contactIds||[]).includes(c.id)?'selected':''}>${esc(c.name)} · ${esc(institution(c.institutionId))}</option>`).join('')}</select></label>${area('Instructions','instructions',v.instructions)}</div>`,async (fd,intent)=>{const values=Object.fromEntries(fd);delete values.organizer;values.institutionIds=fd.getAll('institutionIds');values.contactIds=fd.getAll('contactIds');const r=await store.saveEvent(u.id,values,e?.id,intent==='submit');selected=r.id;page='Events';toast(intent==='submit'?'Event submitted for approval.':'Draft saved. Submit when you’re ready.')},'Save as Draft');const form=document.querySelector('#modal-form');form.querySelector('[name=institutionIds]').onchange=()=>{const targets=[...form.querySelector('[name=institutionIds]').selectedOptions].map(o=>o.value),contacts=form.querySelector('[name=contactIds]'),chosen=[...contacts.selectedOptions].map(o=>o.value);contacts.innerHTML=data.contacts.filter(c=>!targets.length||targets.includes(c.institutionId)).map(c=>`<option value="${attr(c.id)}" ${chosen.includes(c.id)?'selected':''}>${esc(c.name)} · ${esc(institution(c.institutionId))}</option>`).join('')}}
function institutionForm(record){const v=record||{name:'',type:'School',region:'',status:'New lead'};openModal(record?'Edit institution':'Add an institution',`<div class="form-grid">${field('Institution name *','name',v.name,'text',true,true)}${select('Institution type','type',['School','College','Other'],v.type)}${select('Relationship status','status',['New lead','In conversation','Active partner','Inactive'],v.status)}${field('Address / region *','region',v.region,'text',true,true)}</div>`,async fd=>{await store.saveInstitution(session,Object.fromEntries(fd),record?.id);toast('Institution saved.')})}
function institutionDetail(recordId){const i=data.institutions.find(x=>x.id===recordId);if(!i)return;const u=user(),cs=data.contacts.filter(c=>c.institutionId===i.id),es=data.events.filter(e=>e.institutionIds.includes(i.id)&&(!['Student','Institution contact'].includes(u.role)||['Published','Completed','Cancelled'].includes(e.status)));openModal(esc(i.name),`<div class="detail-pair"><span>Region</span><b>${esc(i.region)}</b></div><div class="detail-pair"><span>Relationship</span>${tag(i.status)}</div><div class="section-heading"><h2>People & contacts</h2>${canManage(u)?button('Add contact','new-contact',i.id):''}</div>${cs.map(c=>`<div class="notice"><b>${esc(c.name)}</b> · ${esc(c.designation)} ${c.id===i.primaryContactId?tag('Primary contact'):''}<br>${esc(c.email)} · ${esc(c.phone)} ${canManage(u)?button('Edit','edit-contact',c.id)+(c.id!==i.primaryContactId?' '+button('Make primary','primary-contact',i.id+':'+c.id):''):''}</div>`).join('')||'<p class="small-muted">No contacts have been added yet.</p>'}<div class="section-heading"><h2>Engagement history</h2></div>${es.map(e=>`<div class="detail-pair"><span>${esc(e.title)}<br>${formatDate(e.date)}</span>${tag(e.status)}</div>`).join('')||'<p class="small-muted">No engagement history yet.</p>'}${canManage(u)?`<div class="modal-footer">${button('Edit institution','edit-institution',i.id,'primary')}</div>`:''}`)}
function contactForm(institutionId,record){const v=record||{institutionId,name:'',designation:'',email:'',phone:''};openModal(record?'Edit contact':'Add an institution contact',`<div class="form-grid">${select('Institution','institutionId',data.institutions.map(i=>[i.id,i.name]),v.institutionId,true)}${field('Full name *','name',v.name,'text',true)}${field('Designation','designation',v.designation)}${field('Email *','email',v.email,'email',true)}${field('Phone','phone',v.phone,'tel')}</div>`,async fd=>{await store.saveContact(session,Object.fromEntries(fd),record?.id);toast('Contact saved.')})}
function review(eventId){const e=store.event(eventId);openModal('Review event proposal',`<h3>${esc(e.title)}</h3><p class="confirmation">${esc(e.description)}</p><div class="detail-pair"><span>Organizer / category</span><b>${esc(person(e.organizerId))} · ${esc(e.category)}</b></div><div class="detail-pair"><span>Event date / time</span><b>${formatDate(e.date)} · ${esc(e.startTime)}–${esc(e.endTime)} IST</b></div><div class="detail-pair"><span>Target institutions</span><b>${esc(e.institutionIds.map(institution).join(', ')||'All institutions')}</b></div><p class="small-muted">Instructions: ${esc(e.instructions||'None')}</p><div class="detail-pair"><span>Venue / capacity</span><b>${esc(e.venue)} · ${e.capacity}</b></div><div class="detail-pair"><span>Registration period</span><b>${formatDate(e.registrationStart)} – ${formatDate(e.registrationEnd)}</b></div><div class="detail-pair"><span>Eligibility</span><b>${esc(e.eligibility)}</b></div><div class="form-grid">${select('Decision','decision',['approve','reject'],'approve',true)}${area('Comments / rejection reason','comments','')}</div>`,async fd=>{await store.transition(session,e.id,fd.get('decision'),fd.get('comments'));toast('Decision recorded. The coordinator has been notified.')},'Record decision')}
function outcomeForm(){const es=data.events.filter(e=>['Published','Completed'].includes(e.status)&&eventHasEnded(e));if(!es.length){toast('Outcomes require an event that has taken place.');return}openModal('Record an outreach outcome',`<div class="form-grid">${select('Event','eventId',es.map(e=>[e.id,e.title]),es[0].id,true)}${field('Institutions engaged','institutionsEngaged',0,'number',true)}${field('Participants reached','participantsReached',0,'number',true)}${field('Leads generated','leads',0,'number',true)}${area('Feedback *','feedback','',true)}${area('Follow-up actions','followUp','')}${area('Outcome notes','notes','')}<label><span>Follow-up required</span><input type="checkbox" name="followUpRequired"></label></div>`,async fd=>{const values=Object.fromEntries(fd);values.followUpRequired=fd.has('followUpRequired');await store.recordOutcome(session,values);toast('Outcome recorded.')})}
function userForm(targetId){const u=data.users.find(x=>x.id===targetId);openModal('Manage user account',`<p class="confirmation"><b>${esc(u.name)}</b><br>${esc(u.email)}</p><div class="form-grid">${select('Role','role',ROLES,u.role)}${select('Account status','status',['Active','Inactive'],u.status)}${select('Institution (required for institution contacts)','institutionId',[['','Not linked'],...data.institutions.map(i=>[i.id,i.name])],u.institutionId||'',true)}</div>`,async fd=>{await store.updateUser(session,u.id,Object.fromEntries(fd));toast('Account updated.')})}
function download(name,content,mime){const url=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvCell(v){let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function csv(name,rows){download(name,rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function exportReport(){store.require(session,canReport);csv('InstituteConnect-event-report.csv',[['Event','Date','Category','Status','Registrations','Capacity','Attendance records','Leads'],...data.events.map(e=>[e.title,e.date,e.category,e.status,store.count(e.id),e.capacity,data.participation.filter(p=>p.eventId===e.id&&p.status==='Present').length,data.outcomes.filter(o=>o.eventId===e.id).reduce((n,o)=>n+o.leads,0)])]);toast('Report exported.')}
function guide(){openModal('A quick tour of InstituteConnect',`<p class="confirmation">All users sign in with their own verified email address. Administrators assign coordinator, approver, institution contact, and management roles.</p><div class="notice"><b>1. Plan</b> · Coordinators create a draft and submit it.<br><b>2. Review</b> · Approvers approve or reject with a reason.<br><b>3. Publish</b> · The organizer publishes the approved event.<br><b>4. Participate</b> · Students and institution contacts register while places are available.<br><b>5. Measure</b> · Record attendance and outcomes after an event ends, then export reports.</div><p class="small-muted">Records are shared across devices. Every server operation checks your role and relevant ownership. Notifications are delivered in-app.</p>`)}

function participationPage(u){
 const ps=store.visibleParticipation(u.id),staff=canManage(u);
 return heading(staff?'Be there. Make it count.':'Your participation history',staff?'Record and correct participation in completed outreach activities.':'Your recorded activities and attendance, in one place.',staff?button(icon('plus')+' &nbsp; Record attendance','new-participation','','primary')+button('Export participation CSV','export-participation'):'')+
 rowsTable(['PARTICIPANT','EVENT / ACTIVITY','ATTENDANCE','RECORDED',...(staff?['']:[])],ps.map(p=>`<tr><td><b>${esc(person(p.userId))}</b></td><td>${esc(store.event(p.eventId).title)}<small>${esc(p.activity)}</small></td><td>${tag(p.status)}</td><td>${formatDate(p.date)}</td>${staff?`<td>${button('Correct attendance','edit-participation',p.id)}</td>`:''}</tr>`));
}
function publishedForm(e){
 openModal('Update published event logistics',`<p class="small-muted">Update the schedule, location, or instructions. Confirmed participants receive an in-app update. The approved title, audience, eligibility, and capacity stay fixed.</p><div class="form-grid">${field('Event date *','date',e.date,'date',true)}${field('Venue *','venue',e.venue,'text',true)}${field('Start time (IST) *','startTime',e.startTime,'time',true)}${field('End time (IST) *','endTime',e.endTime,'time',true)}${area('Instructions','instructions',e.instructions)}</div>`,async fd=>{const count=await store.updatePublishedEvent(session,e.id,Object.fromEntries(fd));toast(`Event updated. ${count} registrants notified.`)},'Save & notify participants');
}
function participationForm(record){
 const es=data.events.filter(e=>['Published','Completed'].includes(e.status)&&eventHasEnded(e));
 if(!es.length){toast('No finished events are ready for attendance.');return}
 const selectedEvent=record?.eventId||es[0].id;
 const participants=eid=>data.registrations.filter(r=>r.status==='Confirmed'&&r.eventId===eid).map(r=>[r.userId,person(r.userId)]);
 openModal(record?'Correct participation':'Record participation',`<p class="small-muted">Attendance is available after an event’s scheduled end time. Only confirmed registrants of the selected event are listed.</p><div class="form-grid">${select('Event','eventId',es.map(e=>[e.id,e.title]),selectedEvent,true)}${select('Participant','userId',participants(selectedEvent),record?.userId||'')}${select('Attendance','status',['Present','Absent','Excused'],record?.status||'Present')}${field('Activity *','activity',record?.activity||'Engineering lab tour','text',true,true)}</div>`,async fd=>{await store.recordParticipation(session,Object.fromEntries(fd));toast('Participation saved.')});
 const form=document.querySelector('#modal-form'),eventSelect=form.querySelector('[name=eventId]'),participantSelect=form.querySelector('[name=userId]');
 if(record){eventSelect.disabled=true;participantSelect.disabled=true;form.querySelector('[name=activity]').readOnly=true;form.addEventListener('formdata',ev=>{ev.formData.set('eventId',record.eventId);ev.formData.set('userId',record.userId)})}
 else eventSelect.onchange=()=>{participantSelect.innerHTML=participants(eventSelect.value).map(([id,name])=>`<option value="${attr(id)}">${esc(name)}</option>`).join('')};
}
function profileForm(){const u=user();openModal('My profile',`<p class="confirmation"><b>${esc(u.name)}</b> · <span class="tag">${esc(u.role)}</span><br><small class="small-muted">${esc(u.email)}</small></p><div class="form-grid">${field('Full name *','name',u.name,'text',true,true)}${field('Contact phone','phone',u.phone||'','tel',false,true)}${u.role==='Student'?select('Education level','level',['Class 10','Class 11','Class 12','Undergraduate'],u.level,true):''}</div><p class="small-muted">Your email and assigned role are managed separately. Eligibility uses your education level.</p>`,async fd=>{await store.updateProfile(session,Object.fromEntries(fd));toast('Account details updated.')})}
function configurationForm(){const config=data.settings;openModal('Default event settings',`<div class="form-grid">${field('Default capacity *','defaultCapacity',config.defaultCapacity,'number',true)}${select('Default mode','defaultMode',['Offline','Online','Hybrid'],config.defaultMode)}</div><p class="small-muted">Applies to new drafts only. Existing events keep their approved details.</p>`,async fd=>{await store.updateConfiguration(session,Object.fromEntries(fd));toast('Default event settings updated.')})}
function settingsPage(u){return heading('Make yourself at home.','Your account, event preferences, and workspace information.')+`<div class="panel"><div class="settings-row"><div><b>${esc(u.name)}</b><p>${esc(u.email)} · ${esc(u.role)}${u.phone?' · '+esc(u.phone):''}</p></div>${button('Edit my profile','profile')}</div><div class="settings-row"><div><b>Appearance theme</b><p>${theme==='dark'?'Dark mode is currently active':'Light mode is currently active'}</p></div>${button(icon(theme==='dark'?'sun':'moon')+' &nbsp; '+(theme==='dark'?'Switch to light mode':'Switch to dark mode'),'toggle-theme')}</div><div class="settings-row"><div><b>Sign out securely</b><p>End this session on your device.</p></div>${button('Sign out','logout')}</div>${u.role==='Administrator'?`<div class="settings-row"><div><b>Default event settings</b><p>${data.settings.defaultCapacity} places · ${esc(data.settings.defaultMode)} · applies to new drafts</p></div>${button('Configure defaults','configuration')}</div><div class="settings-row"><div><b>Workspace backup</b><p>Download a JSON snapshot of the shared workspace records.</p></div>${button('Download backup','backup')}</div><div class="settings-row"><div><b>System activity</b><p>Review administrative and outreach changes.</p></div>${button('Open audit log','nav','Audit log')}</div>`:''}<div class="settings-row"><div><b>About InstituteConnect</b><p>Team T005 · CS314 · LNMIIT, Jaipur</p></div>${button('Workspace guide','guide')}</div></div><div class="notice">Accounts use managed authentication. Records are stored in the shared database, and access is checked on the server. Notifications are delivered in-app.</div>`}
function exportParticipation(){store.require(session,canReport);csv('InstituteConnect-participation-report.csv',[['Event','Activity','Participant','Institution','Attendance','Recorded'],...data.participation.map(p=>[store.event(p.eventId).title,p.activity,person(p.userId),institution(p.institutionId||data.users.find(u=>u.id===p.userId)?.institutionId),p.status,p.date])]);toast('Participation report exported.')}
function exportOutcomes(){store.require(session,canReport);csv('InstituteConnect-outcome-report.csv',[['Event','Event date','Institutions engaged','Leads generated','Feedback','Follow-up actions','Recorded'],...data.outcomes.map(o=>[store.event(o.eventId).title,store.event(o.eventId).date,o.institutionsEngaged,o.leads,o.feedback,o.followUp,o.date])]);toast('Outcome report exported.')}

document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const {action,value}=b.dataset;try{switch(action){case 'portal-select':choosePortal(value);authMode='login';await bootstrap();break;case 'portal-back':choosePortal(null);roleSelection();break;case 'clear-filters':query='';statusFilter='All statuses';categoryFilter='All categories';eventDate='';registrationEvent='All events';registrationStatus='All statuses';institutionType='All types';relationship='All relationships';render();break;case 'refresh':await bootstrap();break;case 'auth-mode':authMode=value;login();break;case 'send-code':await sendVerificationCode();break;case 'logout':await authClient.signOut();session=null;authIdentity=null;data=emptyState();store=new ServerWorkspace(data);selected=null;menuOpen=false;authMode='login';choosePortal(null);modal.close();login();break;case 'nav':page=value;query='';statusFilter='All statuses';categoryFilter='All categories';eventDate='';registrationEvent='All events';registrationStatus='All statuses';institutionType='All types';relationship='All relationships';selected=null;menuOpen=false;render();break;case 'menu':menuOpen=!menuOpen;render();break;case 'toggle-theme':toggleTheme();if(!user()){login()}else{render()}break;case 'profile':profileForm();break;case 'configuration':configurationForm();break;case 'update-published':publishedForm(store.event(value));break;case 'primary-contact':{const [iid,cid]=value.split(':');await store.setPrimaryContact(session,iid,cid);persist();modal.close();institutionDetail(iid);break}case 'edit-participation':participationForm(data.participation.find(p=>p.id===value));break;case 'export-participation':exportParticipation();break;case 'export-outcomes':exportOutcomes();break;case 'new-event':eventForm();break;case 'edit-event':eventForm(store.event(value));break;case 'event':page='Events';selected=value;render();window.scrollTo(0,0);break;case 'back-events':selected=null;render();break;case 'transition':{const [eventId,action]=value.split(':');run(()=>store.transition(session,eventId,action),'Event updated.');break}case 'confirm-cancel':openModal('Cancel this outreach event?',`<p class="confirmation">${esc(store.event(value).title)} will no longer accept registrations. Confirmed participants will receive an in-app cancellation notification.</p>`,async()=>{await store.transition(session,value,'cancel');toast('Event cancelled.')},'Cancel event');break;case 'review':if(store.event(value).status==='Pending')await store.transition(session,value,'startReview');review(value);break;case 'register':run(()=>store.register(session,value),'Your place is confirmed. See Registrations for details.');break;case 'cancel-registration':openModal('Cancel your registration?',`<p class="confirmation">Your place will be released. You can register again while registration is open and places remain.</p>`,async()=>{await store.cancelRegistration(session,value);toast('Registration cancelled.')},'Confirm cancellation');break;case 'reminder':run(async()=>{const n=await store.reminders(session,value);toast(`${n} in-app reminders created.`)});break;case 'new-institution':institutionForm();break;case 'institution':institutionDetail(value);break;case 'edit-institution':modal.close();institutionForm(data.institutions.find(i=>i.id===value));break;case 'new-contact':modal.close();contactForm(value);break;case 'edit-contact':{const c=data.contacts.find(x=>x.id===value);modal.close();contactForm(c.institutionId,c);break}case 'new-participation':participationForm();break;case 'new-outcome':outcomeForm();break;case 'edit-user':userForm(value);break;case 'close-modal':(document.querySelector('#modal')||modal)?.close();break;case 'read':run(()=>rpc('readNotification',{id:value}));break;case 'read-all':run(()=>rpc('readAllNotifications',{}),'All notifications marked read.');break;case 'export-report':exportReport();break;case 'export-registrations':store.require(session,canManage);csv('InstituteConnect-registrations.csv',[['Reference','Event','Participant','Date','Status'],...filteredRegistrations(user()).map(r=>[r.id,store.event(r.eventId).title,person(r.userId),r.date,r.status])]);toast('Registrations exported.');break;case 'print':window.print();break;case 'backup':store.require(session,u=>u.role==='Administrator');download('InstituteConnect-workspace.json',JSON.stringify(data,null,2),'application/json');toast('Workspace backup downloaded.');break;case 'guide':guide();break;}}catch(e){toast(e.message)}});
document.addEventListener('input',ev=>{if(ev.target.dataset.filter==='search'){query=ev.target.value;const pos=ev.target.selectionStart;render();const input=document.querySelector('[data-filter="search"]');input.focus();input.setSelectionRange(pos,pos)}});
document.addEventListener('change',ev=>{const key=ev.target.dataset.filter;if(key==='event-date')eventDate=ev.target.value;if(key==='registration-event')registrationEvent=ev.target.value;if(key==='registration-status')registrationStatus=ev.target.value;if(key==='institution-type')institutionType=ev.target.value;if(key==='relationship')relationship=ev.target.value;if(['event-date','registration-event','registration-status','institution-type','relationship'].includes(key))render();if(ev.target.dataset.filter==='status'){statusFilter=ev.target.value;render()}if(ev.target.dataset.filter==='category'){categoryFilter=ev.target.value;render()}});
document.addEventListener('click',ev=>{const m=document.querySelector('#modal');if(m&&ev.target===m)m.close()});

async function sendVerificationCode(){try{const result=await authClient.emailOtp.sendVerificationOtp({email:authIdentity.email,type:'email-verification'});if(result.error)throw new Error(result.error.message||'Could not send the code.');toast('Verification code sent. Check your inbox.')}catch(error){toast(error.message)}}
document.addEventListener('submit',async ev=>{if(ev.target.id!=='auth-form')return;ev.preventDefault();const form=ev.target,values=new FormData(form),submit=form.querySelector('[type=submit]'),errorBox=document.querySelector('#auth-error');submit.disabled=true;errorBox.classList.remove('visible');try{
 let response;
 if(authMode==='verify')response=await authClient.emailOtp.verifyEmail({email:authIdentity.email,otp:String(values.get('otp'))});
 else if(authMode==='signup')response=await authClient.signUp.email({name:String(values.get('name')).trim(),email:String(values.get('email')).trim(),password:String(values.get('password'))});
 else response=await authClient.signIn.email({email:String(values.get('email')).trim(),password:String(values.get('password'))});
 if(response.error)throw new Error(authMode==='login'?'Sign-in failed. Check your email and password.':response.error.message||'The request could not be completed.');
 const sessionResponse=await authClient.getSession();authIdentity=sessionResponse.data?.user||response.data?.user||null;
 if(authIdentity&&!authIdentity.emailVerified){authMode='verify';login();await sendVerificationCode()}else await loadWorkspace();
 }catch(error){errorBox.textContent=error.message;errorBox.classList.add('visible')}finally{submit.disabled=false}});
async function bootstrap(){if(!portal){roleSelection();return}try{const result=await authClient.getSession();if(result.error)throw new Error('The sign-in service is temporarily unavailable.');authIdentity=result.data?.user||null;if(authIdentity)await loadWorkspace();else login()}catch(e){app.innerHTML=`<div class="empty"><h2>Unable to connect.</h2><p>${esc(e.message)}</p>${button('Try again','refresh')}</div>`}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&session&&!modal.open)loadWorkspace()});
setInterval(()=>{if(session&&document.visibilityState==='visible'&&!modal.open)loadWorkspace()},30000);
bootstrap();
